class Handler(BaseHTTPRequestHandler):
    def log_message(self, *args):
        pass

    def _send(self, code, body, ctype="application/json; charset=utf-8"):
        data = body if isinstance(body, bytes) else json.dumps(body, ensure_ascii=False).encode()
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(data)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        self.wfile.write(data)

    def do_GET(self):
        path = self.path.split("?")[0]
        if path in ("/", "/index.html"):
            self._send(200, open(os.path.join(HERE, "ui", "index.html"), "rb").read(), "text/html; charset=utf-8")
        elif path in ("/3d", "/3d.html"):
            self._send(200, open(os.path.join(HERE, "ui", "3d.html"), "rb").read(), "text/html; charset=utf-8")
        elif path.startswith("/vendor/") or path.endswith(".js"):
            self._static(path)
        elif path == "/api/layout":
            self._send(200, layout())
        elif path == "/api/state":
            self._send(200, TWIN.state())
        elif path == "/api/history":
            with TWIN.lock:
                self._send(200, TWIN.history)
        elif path == "/api/twins":
            try:
                res = ditto_request("GET", f"/search/things?filter=like(thingId,%22{NS}:*%22)&option=size(200)")
                self._send(200, res)
            except (urllib.error.URLError, OSError) as exc:
                self._send(502, {"error": str(exc)})
        elif path == "/healthz":
            self._send(200, {"ok": True, "t": TWIN.model.t})
        else:
            self._send(404, {"error": "not found"})

    def _static(self, path):
        """Files under ui/ (three.js and the 3D scene), never outside it."""
        root = os.path.realpath(os.path.join(HERE, "ui"))
        full = os.path.realpath(os.path.join(root, path.lstrip("/")))
        if not full.startswith(root + os.sep) or not os.path.isfile(full):
            return self._send(404, {"error": "not found"})
        ctype = {".js": "text/javascript; charset=utf-8", ".html": "text/html; charset=utf-8",
                 ".png": "image/png"}.get(os.path.splitext(full)[1], "application/octet-stream")
        self._send(200, open(full, "rb").read(), ctype)

    def do_POST(self):
        length = int(self.headers.get("Content-Length") or 0)
        try:
            body = json.loads(self.rfile.read(length) or b"{}")
        except ValueError:
            return self._send(400, {"error": "bad json"})
        path = self.path.split("?")[0]
        if path == "/api/command":
            if not body.get("cmd"):
                return self._send(400, {"error": "cmd required"})
            self._send(200, {"result": send_command(body)})
        elif path == "/api/sim":
            if "speed" in body:
                TWIN.speed = max(0.0, min(120.0, float(body["speed"])))
            if "paused" in body:
                TWIN.paused = bool(body["paused"])
            self._send(200, {"speed": TWIN.speed, "paused": TWIN.paused})
        elif path == "/api/forecast":
            TWIN.forecast_due = 0.0
            self._send(200, {"ok": True})
        else:
            self._send(404, {"error": "not found"})


